-- 보충 에세이 정책 시드 (2026-08-30 리서치, 공식 입학처 출처 — 톱40 종합대+LAC10, USC는 공식 미게시로 제외)
update public.schools set essay_req='필수 에세이 3편(학업 관심 250단어, 생활경험·커뮤니티 400-500단어, 봉사·시민참여 250단어) + 짧은 답변 3개(각 50단어) — 전년과 동일.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admission.princeton.edu/apply/princeton-specific-questions' where id=1;
update public.schools set essay_req='필수 에세이 4개(각 100-200단어) + 필수 단답 4개(각 40-50단어).', essay_change='에세이를 5개에서 4개로 줄이고(협업 문항 폐지) 40-50단어 단답 4개(재미로 하는 일, 존경하는 사람, 몇 시간이고 이야기할 주제, generalist/specialist)를 신설 — ''재미로 하는 일''은 150단어 에세이에서 단답으로 축소.', essay_cycle='2026-27', essay_source_url='https://mitadmissions.org/apply/firstyear/essays-activities-academics/' where id=2;
update public.schools set essay_req='필수 단답 5개(각 150단어: 기여, 의견 불일치 경험, 활동·책임, 하버드 교육 활용 계획, 룸메이트에게 알릴 3가지) — 전년과 동일.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://college.harvard.edu/admissions/apply/application-requirements' where id=3;
update public.schools set essay_req='필수 단문 5개(각 최대 50단어) + 짧은 에세이 3편(각 100-250단어: 배움의 설렘, 룸메이트에게 쓰는 노트, 스탠퍼드에 기여할 점) — 전년과 동일.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admission.stanford.edu/apply/freshman/apply.html' where id=4;
update public.schools set essay_req='학업 분야 선택 + 학업 관심 에세이(200단어) + Short Takes 3개(각 200자) + 400단어 에세이 1편(3개 프롬프트 중 택1).', essay_change='''Why Yale''(125단어) 문항을 폐지하고 Short Takes를 4개에서 3개(각 200자)로 축소 개편.', essay_cycle='2026-27', essay_source_url='https://admissions.yale.edu/essay-topics' where id=5;
update public.schools set essay_req='필수 2편: ''Why UChicago'' + 확장(Uncommon) 에세이 1편(6개 옵션 중 택1) — 구조 동일, 옵션 주제만 예년처럼 연례 교체.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://collegeadmissions.uchicago.edu/apply/essay/' where id=6;
update public.schools set essay_req='필수 에세이 2편(Why Duke 250단어 + 커뮤니티 250단어) + 선택 3개 프롬프트 중 최대 1개(250단어).', essay_change='필수 에세이가 1편에서 2편으로 확대(커뮤니티 문항 필수화)되고 선택 프롬프트는 5개→3개(최대 1개 응답)로 축소, 지난 사이클에 도입됐던 AI 관련 선택 문항은 1년 만에 폐지.', essay_cycle='2026-27', essay_source_url='https://admissions.duke.edu/apply/' where id=7;
update public.schools set essay_req='필수 에세이 1편(350단어): 차이를 넘어 관계 맺기(engaging across differences)와 브리지 빌딩·커뮤니티에 관한 문항.', essay_change='1편 체제는 유지하되 주제를 교체 — 150주년 기념 ''important first(인생의 중요한 첫 경험)'' 문항에서 ''차이를 넘는 대화·브리지 빌딩'' 문항으로 변경.', essay_cycle='2026-27', essay_source_url='https://apply.jhu.edu/hopkins-insider/advice-for-crafting-your-supplemental-essay/' where id=8;
update public.schools set essay_req='필수 단답 1개(300단어, 자신의 배경이 Northwestern 커뮤니티 참여에 미칠 영향) + 선택 프롬프트 5개 중 최대 2개(각 200단어); Common App 개인 에세이(personal essay)는 선택 제출로 전환.', essay_change='''Why Northwestern'' 필수 문항을 배경·커뮤니티 참여 문항으로 교체하고, Common App 개인 에세이를 필수에서 선택으로 전환(다른 지원서용 에세이 재활용 허용).', essay_cycle='2026-27', essay_source_url='https://admissions.northwestern.edu/apply/requirements.html' where id=9;
update public.schools set essay_req='필수 3편(각 150-200단어): 감사 노트(thank-you note), 커뮤니티, 지원 스쿨별(school-specific) 문항 + 듀얼디그리·특수 프로그램은 추가 에세이 — 전년과 동일.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admissions.upenn.edu/how-to-apply/preparing-your-application/essays-prompts' where id=10;
update public.schools set essay_req='필수 응답 5개(관심분야 2부 구성 150-200단어, ''학자적 태도'' 2개 중 택1 200단어, ''과학적 탐구'' 3개 중 택2 각 200단어, 커뮤니티 기여 재미 문항 100-150단어) + 선택 1개(학업 맥락 설명).', essay_change='문항 전면 개편 — 기존 STEM 흥미 발견 과정·창의성(creator/inventor) 문항을 폐지하고 선택형(2개 중 택1, 3개 중 택2) 구조를 도입했으며, 제출 전 AI 윤리적 사용 가이드라인 확인 절차를 신설.', essay_cycle='2026-27', essay_source_url='https://www.admissions.caltech.edu/apply/first-year-applicants/supplemental-application-essays' where id=11;
update public.schools set essay_req='대학 공통(university-wide) 에세이 없음 — 지원 단과대별 에세이만 작성(예: Arts & Sciences 650단어 1편, CALS 350단어 2편, Engineering 에세이 2편+단답 4개).', essay_change='전 지원자 공통이던 커뮤니티 에세이(350단어)를 폐지해 단과대별 에세이만 남기고, CALS는 500단어 1편에서 350단어 2편으로 개편.', essay_cycle='2026-27', essay_source_url='https://admissions.cornell.edu/how-to-apply/first-year-applicants/cornell-first-year-writing-supplement-prompts' where id=12;
update public.schools set essay_req='필수 에세이 4편: 오픈 커리큘럼(150-250단어), 성장 배경·기여(150-250단어), 가르치고 싶은 수업(100-150단어), 기쁨을 주는 것(100-150단어).', essay_change='서플먼트 개편 — 기존 ''에세이 3편+단답'' 구성에서 단답 섹션(3단어 자기소개, 한 문장 Why Brown 등)을 폐지하고 오픈 커리큘럼 문항을 새로 써서 에세이 4편 체제로 변경.', essay_cycle='2026-27', essay_source_url='https://admission.brown.edu/apply/how-apply' where id=13;
update public.schools set essay_req='필수 에세이 3개: Why Dartmouth 100단어 + 250단어 2개(각각 2지선다·6지선다 옵션 중 택1). 최근 두 사이클 동안 구조 동일, 옵션 프롬프트만 일부 교체.', essay_change=null, essay_cycle='None', essay_source_url='https://admissions.dartmouth.edu/glossary-term/writing-supplement' where id=14;
update public.schools set essay_req='리스트형 1개(지적 성장에 기여한 텍스트·자료 목록, 100단어) + 150단어 단답 5개(lived experience, 의견 불일치 경험, 역경 극복, Why Columbia, 전공 관심). 2023-24 개편 이후 세트 유지.', essay_change=null, essay_cycle='None', essay_source_url='https://undergrad.admissions.columbia.edu/apply/process/columbia-questions' where id=15;
update public.schools set essay_req='UC 지원서 PIQ: 8문항 중 4개 선택, 각 350단어 이내. Fall 2027 지원(2026-27 사이클)에도 개수·정책 변화 없음.', essay_change=null, essay_cycle='None', essay_source_url='https://admission.universityofcalifornia.edu/how-to-apply/applying-as-a-freshman/personal-insight-questions.html' where id=16;
update public.schools set essay_req='필수 에세이 3개(전공 관심 150단어 + Rice 경험 150단어 + 500단어 택1: 기숙칼리지 기여 또는 change agent) + 이미지 업로드 ''The Box''. 최근 두 사이클 구조 동일.', essay_change=null, essay_cycle='None', essay_source_url='https://admission.rice.edu/apply/first-year-domestic-applicants' where id=17;
update public.schools set essay_req='UC 지원서 PIQ: 8문항 중 4개 선택, 각 350단어 이내. Fall 2027 지원(2026-27 사이클)에도 개수·정책 변화 없음.', essay_change=null, essay_cycle='None', essay_source_url='https://admission.universityofcalifornia.edu/how-to-apply/applying-as-a-freshman/personal-insight-questions.html' where id=18;
update public.schools set essay_req='필수 단답 1개(약 250단어): 교훈(motto) ''Crescere aude(dare to grow)''를 주제로 정체성·문화·배경이 성장에 미친 영향과 캠퍼스 기여를 묻는 프롬프트. 2026-27에도 동일 유지.', essay_change='2025-26 사이클에 오랫동안 쓰던 교과외활동(extracurricular) 서술 프롬프트를 폐지하고 ''Crescere aude'' 정체성·성장 프롬프트로 교체(에세이 개수는 1개로 동일).', essay_cycle='2025-26', essay_source_url='https://admissions.vanderbilt.edu/apply/personal-essay-and-short-answer-prompts/' where id=19;
update public.schools set essay_req='필수 단답 3개(각 300단어 이내): 전공 선택 계기, 성공적인 대학 경험의 정의, 강조하고 싶은 점. 최근 두 사이클 프롬프트 그대로 유지.', essay_change=null, essay_cycle='None', essay_source_url='https://www.cmu.edu/admission/admission/undergraduate-admission-requirements' where id=20;
update public.schools set essay_req='필수 U-M 에세이 2개: 리더십·시민의식으로 U-M 비전에 기여할 준비(100-300단어) + 지원 단과대학 선택 이유(100-550단어), 선택형 challenges 에세이 1개. 2026-27에도 동일.', essay_change='2025-26 사이클에 오래 유지하던 ''커뮤니티와 그 안에서의 나'' 에세이를 폐지하고 리더십·시민의식(비전 기여) 프롬프트로 교체(필수 2개 구조는 유지).', essay_cycle='2025-26', essay_source_url='https://teamdynamix.umich.edu/TDClient/154/Portal/KB/ArticleDet?ID=7424' where id=21;
update public.schools set essay_req='필수 에세이 1개(150단어, 대학 선택의 non-negotiable 요소) + 단답 4개 중 2개 선택(각 50-100단어: 신앙, 개인 경험, 봉사 등).', essay_change='2026-27 사이클에 응답 수를 5개(필수 에세이 2 + 단답 5중3)에서 3개(필수 에세이 1 + 단답 4중2)로 축소.', essay_cycle='2026-27', essay_source_url='https://admissions.nd.edu/apply/application-overview/' where id=22;
update public.schools set essay_req='필수 에세이 1개(250단어, 무엇을 공부하고 싶은지와 이유) + 선택형 90초 영상 소개. 선택형 글쓰기 서플은 더 이상 없음.', essay_change='2026-27 사이클에 선택형 에세이 문항(커뮤니티/By Name & Story 등)을 전부 폐지하고 필수 전공 관심 에세이 1개(250단어)와 선택 영상만 유지.', essay_cycle='2026-27', essay_source_url='https://admissions.washu.edu/how-to-apply/first-year-us-applicants/' where id=23;
update public.schools set essay_req='단답 2개: 학업 관심 분야와 이유(200단어) + 4개 옵션 중 택1(150단어). 2026-27 문항은 직전 사이클과 동일 세트로 공개(공식 페이지는 단답 존재만 명시, 세부 개수·단어수는 서드파티 확인).', essay_change=null, essay_cycle='None', essay_source_url='https://apply.emory.edu/apply/first-year.html' where id=24;
update public.schools set essay_req='필수 에세이 4개: 가장 몰입한 활동 250단어 + 관점이 다른 사람과의 경험 250단어(신설) + 개인·창작 에세이 650단어 + 지원 스쿨별 에세이 500단어. Common App 또는 자체 지원서로 제출.', essay_change='2026-27 사이클(Fall 2027 입학)부터 처음으로 Common App을 도입하고 서플을 개편 — ''다른 관점과의 만남'' 250단어 에세이 신설, 기존 특기·재능(talents) 문항 폐지, ''1페이지 분량'' 대신 단어 수 제한 명시.', essay_cycle='2026-27', essay_source_url='https://uadmissions.georgetown.edu/apply/first-year-applicants/application-requirements-and-forms/' where id=25;
update public.schools set essay_req='서플리멘털 에세이 없음. Common App 개인 에세이(250-650단어)만 요구.', essay_change='2026-27 사이클에 기존 필수 단답 2개(각 250단어)를 전면 폐지 — 지원 절차 단순화를 위해 서플리멘털 에세이를 없앰(공식 공지).', essay_cycle='2026-27', essay_source_url='https://admissions.unc.edu/short-essays-removed-from-carolinas-2026-2027-application/' where id=26;
update public.schools set essay_req='2026-27: 일반 지원자는 UVA 자체 supplemental essay 없음 — Common App 개인 에세이만 제출. 공식 지원 안내(2026-27) 어디에도 supplement 문항이 없음. School of Nursing 지원자만 간호 관련 경험 에세이 1개(250단어)가 요구되는 것으로 보도됨(공식 페이지에는 미기재).', essay_change='2025-26 사이클부터 기존 필수 short-answer 프롬프트(약 100단어 ''personality/background'' 문항 등)를 전면 삭제해 supplement가 사라졌고, 2026-27에도 무(無)supplement 기조가 유지된다(간호대만 예외).', essay_cycle='2025-26 (removal), 2026-27 유지', essay_source_url='https://admission.virginia.edu/admission/deadlines-instructions' where id=27;
update public.schools set essay_req='UC 지원서 Personal Insight Questions: 8개 중 4개 선택, 각 최대 350단어. 캠퍼스별 추가 에세이 없음. 2025-26·2026-27 모두 동일.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admission.universityofcalifornia.edu/how-to-apply/applying-as-a-freshman/personal-insight-questions.html' where id=29;
update public.schools set essay_req='UF 자체 supplemental essay 없음. Common App 개인 에세이는 필수. Honors Program·Innovation Academy 지원자만 선택적 추가 에세이 있음. 최근 두 사이클 간 변경 확인 안 됨.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admissions.ufl.edu/english-common-app-guide' where id=30;
update public.schools set essay_req='에세이 1개(자유 주제, 500-650단어 — Common App 개인 에세이로 충족) + 필수 단답 2개(1지망 전공 관심 / 가장 자랑스러운 활동, 각 250-300단어) + 선택 단답 1개(학업에 영향을 준 상황). 단답 3→2 축소·개인 진술 전환은 Fall 2025 입학(2024-25 사이클)부터 적용된 것으로, 최근 두 사이클 내 변경은 아님.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admissions.utexas.edu/apply/application-materials/essays-and-short-answers/' where id=31;
update public.schools set essay_req='2026-27: 자체 supplemental essay 완전 폐지 — Common App 개인 에세이(7개 프롬프트 중 택1)만 제출. 조지아텍이 읽는 유일한 에세이.', essay_change='2026년 7월 29일 공식 발표: 2026-27 사이클(Fall 2027 입학)부터 ''Why this major at Georgia Tech?'' 단답형 supplement를 폐지 — 입학 판단의 유의미한 변별 요소가 아니라고 판단.', essay_cycle='2026-27', essay_source_url='https://news.em.gatech.edu/2026/07/29/admission-supplemental-essay/' where id=32;
update public.schools set essay_req='선택(optional) supplemental essay 1개 — ''bridge builders''(분열을 잇는 경험) 프롬프트, 250단어 이하. 2025-26과 2026-27 모두 동일한 선택형 프롬프트 유지.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://meet.nyu.edu/advice/application-tips/your-guide-to-the-nyu-supplemental-essay/' where id=33;
update public.schools set essay_req='UC 지원서 Personal Insight Questions: 8개 중 4개 선택, 각 최대 350단어. 캠퍼스별 추가 에세이 없음. 최근 두 사이클 변경 없음.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admission.universityofcalifornia.edu/how-to-apply/applying-as-a-freshman/personal-insight-questions.html' where id=34;
update public.schools set essay_req='UC 지원서 Personal Insight Questions: 8개 중 4개 선택, 각 최대 350단어. 캠퍼스별 추가 에세이 없음. 최근 두 사이클 변경 없음.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admission.universityofcalifornia.edu/how-to-apply/applying-as-a-freshman/personal-insight-questions.html' where id=35;
update public.schools set essay_req='Writing supplement 1개(400단어) — 4개 프롬프트(전통 / 대화 상대 / single story / 예수회 ''4번째 Be'') 중 택1, Human-Centered Engineering 전공은 전용 5번 프롬프트에 답변. 개수·필수 구조는 2025-26과 동일(프롬프트 세트도 사실상 동일).', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.bc.edu/bc-web/admission/apply.html' where id=36;
update public.schools set essay_req='2026-27(Class of 2031): 필수 단문 2개 — ① Tufts를 어떻게 알아보고 engagement했는지(75-150단어), ② 학부별 지정 프롬프트(A&S: 최근 2년간 좋아했던 과제 / 공대: 참여한 엔지니어링·과학 프로젝트 / BFA: 포트폴리오 작품, 각 100-200단어). AI 사용 강력 비권장 명시.', essay_change='2026-27에 ''Why Tufts''(50-100단어)가 학교 탐색 과정을 묻는 75-150단어 프롬프트로 개편되고, 2번째 에세이가 ''3개 중 택1(200-250단어)'' 방식에서 학부별 지정 단일 프롬프트(100-200단어)로 변경됨.', essay_cycle='2026-27', essay_source_url='https://admissions.tufts.edu/apply/essay-questions/' where id=37;
update public.schools set essay_req='전공 선택 관련 필수 에세이 2-3개(1지망 전공 경험·진로 목표 각 ~150단어, 2지망 선택 시 +1개; Undeclared는 대체 프롬프트) + Common App 에세이(250-650단어). 수년간 동일한 형식 유지.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.admissions.illinois.edu/apply/freshman/essays' where id=38;
update public.schools set essay_req='필수 에세이: ''왜 UW-Madison에 다니고 싶은지 + 선택 전공에 대한 관심''(최대 650단어, 권장 300-500) — 모든 지원자 공통. 여기에 Common App 에세이 또는 Universities of Wisconsin 지원서 에세이 1개. 구조 변경 없음.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admissions.wisc.edu/required-materials/' where id=39;
update public.schools set essay_req='UC 지원서 Personal Insight Questions: 8개 중 4개 선택, 각 최대 350단어. 캠퍼스별 추가 에세이 없음. 최근 두 사이클 변경 없음.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://admission.universityofcalifornia.edu/how-to-apply/applying-as-a-freshman/personal-insight-questions.html' where id=40;
update public.schools set essay_req='필수 supplemental essay 없음. 선택으로 academic writing sample(학교 과제물, 채점 여부 무관) 1편 제출 가능 — 에세이 프롬프트 아님.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.williams.edu/admission-aid/how-to-apply/first-year/' where id=64;
update public.schools set essay_req='필수 supplement 1편: Option A(3개 인용문 프롬프트 중 1개, 350단어 이내) / Option B(11-12학년 채점 논문 제출) / Option C(A2A 프로그램 지원자 전용) 중 택1.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.amherst.edu/admission/apply/firstyear/writingsupplement' where id=65;
update public.schools set essay_req='필수 short answer 2문항(각 250단어 이내): ① 자기 정체성·배경과 차이를 넘는 협력 경험 ② 최근 매료된 주제와 지적 호기심. 공식 페이지가 2026-2027 사이클 명시.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.swarthmore.edu/admissions-aid/application-materials-deadlines' where id=66;
update public.schools set essay_req='필수 supplement 에세이 없음. 선택 에세이 2편(각 250단어 이내): ① The Offer of the College 반응 ② Navigating through Differences. 선택 비디오 응답 별도.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.bowdoin.edu/admissions/apply/' where id=67;
update public.schools set essay_req='필수 supplemental essay 2편: ① Why CMC(미션 연계) ② Open Academy(관점이 다른 사람과의 대화로 태도·신념이 바뀐 경험). 선택 2분 비디오 응답 별도.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.cmc.edu/admission/first-year-application-instructions' where id=68;
update public.schools set essay_req='필수 2편: Academic Interest Statement(150단어) + Short-Response Essay(3개 프롬프트 중 택1, 250단어). 단 2026-08-30 현재 공식 페이지는 아직 ''Fall 2026 admission'' 기준으로 표시(2026-27/Fall 2027용 미갱신).', essay_change='2025-26 사이클(Fall 2026)에 3편(150+150+250단어)에서 2편(150+250단어)으로 축소됐고, 2026-27용 프롬프트는 아직 공식 페이지에 미공개.', essay_cycle='2025-26', essay_source_url='https://www.pomona.edu/admissions/apply' where id=69;
update public.schools set essay_req='필수 Wellesley-specific essay 1편: ''build bridges'' 프롬프트(다른 배경·관점의 사람들과 함께 일한 경험) — Common App 개인 에세이(250-650단어)와 별도.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.wellesley.edu/admission-aid/apply/first-year-applicants' where id=70;
update public.schools set essay_req='supplemental essay 없음(Common App 본 에세이만). Carleton Supplement 2026-27 폼은 인적사항·인지 경로 질문과 선택 자유기재란(''Anything missing?'')만 포함, 에세이 프롬프트 없음.', essay_change=null, essay_cycle='2026-27', essay_source_url='https://www.carleton.edu/admissions/apply/steps/materials/' where id=71;
update public.schools set essay_req='필수 추가 작문 2편: ① 경험·커뮤니티가 ''해결하고 싶은 문제와 만들고 싶은 임팩트''를 어떻게 형성했는지(500단어 이내) ② 도움을 요청해 변화를 만든 경험(250단어 이내).', essay_change='2026-27에 두 필수 문항이 전면 교체됨 — 기존(~2025-26) 미션·배경 프롬프트(500단어)+''dream HSA class''(100단어)가 새 경험·임팩트 프롬프트(500단어)+''도움 요청'' 에세이(250단어)로 바뀌고 두 번째 문항 분량이 100→250단어로 확대(2026-05까지 구 프롬프트 게시 확인).', essay_cycle='2026-27', essay_source_url='https://www.hmc.edu/admission/apply/first-year-students/' where id=72;
update public.schools set essay_req='필수 short answer 2문항: ① ''bold question''(50단어 이내) ② 자신과 관점·문제해결 방식이 다르지만 사람들을 모으는 데 뛰어난 여성에게서 얻을 교훈(200-250단어). 공식 페이지가 2026-2027 명시.', essay_change='2025-26에 3문항(200+150+150단어)에서 1문항(200-250단어)으로 축소됐다가, 2026-27에 50단어 ''bold question''이 추가되어 필수 2문항으로 재편됨.', essay_cycle='2025-26 & 2026-27', essay_source_url='https://barnard.edu/barnard-short-answer-questions' where id=73;
